insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('never-outshine-the-master',1,'Never Outshine the Master','কখনো গুরুর চেয়ে বেশি উজ্জ্বল হবেন না','Making superiors feel insecure about their own competence invites silent resentment and eventual removal.','ঊর্ধ্বতনদের নিজেদের যোগ্যতা নিয়ে অসুরক্ষিত মনে করালে তা গভীর অসন্তোষ এবং পরোক্ষ ক্ষতি ডেকে আনে।','power-dynamics','[{"headingEn":"Introduction","headingBn":"ভূমিকা","bodyEn":["Throughout history, those who serve a powerful figure have faced a recurring danger: appearing more capable, more charming, or more brilliant than the person they serve. The lesson is not about hiding your gifts, but about reading the emotional climate around anyone who holds authority over your position.","Insecurity in leadership is common, and a subordinate who accidentally triggers it can find themselves pushed aside without ever being told why. Understanding this dynamic is one of the first steps in navigating any hierarchy, from a university department to a corporate team."],"bodyBn":["ইতিহাস জুড়ে ক্ষমতাশালী ব্যক্তিদের সেবায় যারা ছিলেন, তারা একটি পুনরাবৃত্ত বিপদের সম্মুখীন হয়েছেন: যাঁকে তারা সেবা করেন তার চেয়ে বেশি সক্ষম, বেশি আকর্ষণীয় বা বেশি প্রতিভাবান হিসেবে আবির্ভূত হওয়া। শিক্ষাটি আপনার গুণ লুকানোর বিষয়ে নয়, বরং আপনার অবস্থানের ওপর কর্তৃত্ব রাখেন এমন কারো আশেপাশের আবেগের পরিবেশ পড়তে জানার বিষয়ে।","নেতৃত্বে অনিশ্চয়তা সাধারণ, এবং একজন অধস্তন যদি দুর্ঘটনাক্রমে তা উসকে দেয়, সে নিজেকে কারণ না জানিয়েই পাশে সরে যেতে পারে। এই গতিশীলতা বোঝা যেকোনো স্তরক্রম নেভিগেট করার প্রথম পদক্ষেপগুলির একটি, একটি বিশ্ববিদ্যালয় বিভাগ থেকে শুরু করে একটি কর্পোরেট দল পর্যন্ত।"]},{"headingEn":"Core Principle","headingBn":"মূল নীতি","bodyEn":["The principle is straightforward: people in positions of power are often more sensitive to perceived threats to their status than they let on. When you outshine them publicly, you create a quiet imbalance that they will eventually correct, often subtly.","The skill is in sharing credit, redirecting attention upward, and letting your competence be felt without being flaunted."],"bodyBn":["নীতিটি সরল: ক্ষমতার অবস্থানে থাকা মানুষ প্রায়ই তাদের মর্যাদার প্রতি আপাত হুমকির প্রতি তাদের প্রকাশের চেয়ে বেশি সংবেদনশীল হন। আপনি প্রকাশ্যে তাদের ছাপিয়ে গেলে, আপনি একটি নীরব ভারসাম্যহীনতা তৈরি করেন যা তারা শেষ পর্যন্ত, প্রায়শই সূক্ষ্মভাবে, সংশোধন করবে।","দক্ষতা হলো কৃতিত্ব ভাগ করা, মনোযোগ ঊর্ধ্বে পরিচালিত করা, এবং আপনার যোগ্যতা অহংকার না করে অনুভূত হতে দেওয়া।"]},{"headingEn":"Psychological Explanation","headingBn":"মনস্তাত্ত্বিক ব্যাখ্যা","bodyEn":["This law reflects the psychology of ego threat. When someone''s self-worth is tied to being the most competent person in a room, encountering someone more skilled creates cognitive dissonance.","Rather than updating their self-image, they often resolve the discomfort by devaluing or removing the source of the threat. This is an unconscious self-preservation mechanism, not usually a conscious conspiracy."],"bodyBn":["এই নিয়মটি অহংকারের হুমকির মনস্তত্ত্বকে প্রতিফলিত করে। যখন কারো আত্ম-মূল্য একটি কক্ষে সবচেয়ে যোগ্য ব্যক্তি হওয়ার সাথে যুক্ত, তখন আরও দক্ষ কাউকে দেখা জ্ঞানীয় অসঙ্গতি তৈরি করে।","তারা প্রায়ই নিজেদের আত্ম-চিত্র আপডেট করার পরিবর্তে অস্বস্তি দূর করে হুমকির উৎসকে অবমূল্যায়ন বা অপসারণের মাধ্যমে। এটি একটি অচেতন আত্ম-সংরক্ষণ প্রক্রিয়া, সাধারণত সচেতন ষড়যন্ত্র নয়।"]},{"headingEn":"Real-Life Examples","headingBn":"বাস্তব উদাহরণ","bodyEn":["At university, a student who constantly corrects a professor in front of the class may earn respect from peers but quietly lose access to mentorship and recommendations.","In a workplace, an employee who one-ups their manager in a client meeting may feel they proved their value, but the manager may later reassign the high-visibility projects away from them.","In a friendship, repeatedly being the center of attention when with a friend who is used to that role can strain the relationship over time."],"bodyBn":["বিশ্ববিদ্যালয়ে, একজন ছাত্র যে ক্লাসের সামনে ক্রমাগত একজন অধ্যাপককে সংশোধন করে, সহপাঠীদের কাছ থেকে সম্মান অর্জন করতে পারে কিন্তু নীরবে পরামর্শদাতা এবং সুপারিশের প্রবেশাধিকার হারায়।","কর্মক্ষেত্রে, একজন কর্মী যে একটি ক্লায়েন্ট বৈঠকে তাদের ম্যানেজারকে অতিক্রম করে, নিজের মূল্য প্রমাণ করেছে মনে করতে পারে, কিন্তু ম্যানেজার পরে উচ্চ-দৃশ্যমান প্রকল্পগুলি তাদের থেকে দূরে পুনরায় বরাদ্দ করতে পারেন।","বন্ধুত্বে, যে বন্ধু সেই ভূমিকায় অভ্যস্ত তার সাথে থাকাকালীন বারবার মনোযোগের কেন্দ্র হওয়া সময়ের সাথে সম্পর্কে চাপ সৃষ্টি করতে পারে।"]},{"headingEn":"Practical Application","headingBn":"ব্যবহারিক প্রয়োগ","bodyEn":["Before meetings with leadership, consider what the leader needs to feel confident and in control. Offer ideas privately so they can present them as their own.","When praised publicly, redirect some credit upward. If you are genuinely more skilled in an area, use that skill to make the leader look good rather than to compete with them."],"bodyBn":["নেতৃত্বের সাথে বৈঠকের আগে, নেতা কী নিয়ে আত্মবিশ্বাসী এবং নিয়ন্ত্রণে অনুভব করতে চান তা বিবেচনা করুন। ব্যক্তিগতভাবে ধারণা দিন যাতে তারা সেগুলো নিজেদের হিসেবে উপস্থাপন করতে পারেন।","প্রকাশ্যে প্রশংসিত হলে, কিছু কৃতিত্ব ঊর্ধ্বে পরিচালিত করুন। আপনি যদি কোনো ক্ষেত্রে সত্যিই বেশি দক্ষ হন, সেই দক্ষতা তাদের সাথে প্রতিযোগিতা করার পরিবর্তে নেতাকে ভালো দেখাতে ব্যবহার করুন।"]},{"headingEn":"Defensive Strategy","headingBn":"প্রতিরক্ষামূলক কৌশল","bodyEn":["If you are the one in authority, be aware of this dynamic in yourself. Notice when you feel irritation toward a capable subordinate and ask whether that reaction is about their performance or your insecurity.","Actively elevate people whose competence exceeds your own in specific domains, rather than suppressing them."],"bodyBn":["আপনি যদি কর্তৃত্বে থাকেন, নিজের মধ্যে এই গতিশীলতা সম্পর্কে সচেতন হন। একজন সক্ষম অধস্তনের প্রতি বিরক্তি অনুভব করলে নিজেকে জিজ্ঞাসা করুন সেই প্রতিক্রিয়া তাদের পারফরম্যান্স সম্পর্কে নাকি আপনার অনিশ্চয়তা সম্পর্কে।","নির্দিষ্ট ক্ষেত্রে আপনার চেয়ে যোগ্যতা বেশি এমন মানুষদের দমন করার পরিবর্তে সক্রিয়ভাবে উন্নীত করুন।"]},{"headingEn":"When Not to Apply","headingBn":"যখন প্রয়োগ করা উচিত নয়","bodyEn":["In environments that genuinely reward merit and transparency, such as research teams with strong peer-review cultures, deliberately hiding your competence can slow your growth.","Some leaders actively want to be challenged and are suspicious of excessive deference. Read the specific person, not the archetype."],"bodyBn":["যে পরিবেশগুলি সত্যিই যোগ্যতা এবং স্বচ্ছতাকে পুরস্কৃত করে, যেমন শক্তিশালী পিয়র-রিভিউ সংস্কৃতির গবেষণা দলে, ইচ্ছাকৃতভাবে আপনার যোগ্যতা লুকানো আপনার বৃদ্ধি ধীর করতে পারে।","কিছু নেতা সক্রিয়ভাবে চ্যালেঞ্জ করতে চান এবং অতিরিক্ত বিনীততা সম্পর্কে সন্দেহশীল। আর্কিটাইপ নয়, নির্দিষ্ট ব্যক্তিকে পড়ুন।"]},{"headingEn":"Ethical Considerations","headingBn":"নৈতিক বিবেচনা","bodyEn":["This law can be misread as an instruction to manipulate insecure leaders. A healthier reading is about empathy: understanding that power and insecurity often coexist, and choosing not to inflict unnecessary discomfort on the people you depend on.","The goal is not dishonesty, but tact."],"bodyBn":["এই নিয়মটি অনিরাপদ নেতাদের ম্যানিপুলেট করার নির্দেশ হিসেবে ভুল ব্যাখ্যা করা যেতে পারে। একটি স্বাস্থ্যকর পাঠ হলো সহানুভূতি সম্পর্কে: বোঝা যে ক্ষমতা এবং অনিশ্চয়তা প্রায়ই সহাবস্থান করে, এবং যাদের উপর আপনি নির্ভর করেন তাদের উপর অপ্রয়োজনীয় অস্বস্তি চাপাতে না চাওয়া।","লক্ষ্য অসততা নয়, বরং কৌশল।"]},{"headingEn":"Key Takeaways","headingBn":"মূল শিক্ষা","bodyEn":["Read the emotional needs of people above you, not just their stated requirements.","Let competence be discovered rather than displayed.","Share credit generously, especially upward.","Differentiate between meritocratic environments and ego-driven ones."],"bodyBn":["আপনার উপরের মানুষের আবেগের প্রয়োজন পড়ুন, শুধু তাদের বলা প্রয়োজন নয়।","যোগ্যতা প্রদর্শনের পরিবর্তে আবিষ্কৃত হতে দিন।","কৃতিত্ব উদারভাবে ভাগ করুন, বিশেষত ঊর্ধ্বে।","যোগ্যতাভিত্তিক পরিবেশ এবং অহংকার-চালিত পরিবেশের মধ্যে পার্থক্য করুন।"]}]'::jsonb,null,true,1) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('never-trust-too-much-friends',2,'Never Put Too Much Trust in Friends, Learn How to Use Enemies','বন্ধুদের ওপর খুব বেশি ভরসা করবেন না, শত্রুদের ব্যবহার করতে শিখুন','Friends can grow complacent in professional roles; former adversaries have more to prove and often work harder to earn trust.','পেশাদার ভূমিকায় বন্ধুরা সন্তুষ্ট হতে পারে; প্রাক্তন প্রতিপক্ষদের প্রমাণ করার আরও বেশি আছে এবং তারা প্রায়ই বিশ্বাস অর্জনে আরও কঠোর পরিশ্রম করে।','relationships','[]'::jsonb,null,true,2) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('conceal-your-intentions',3,'Conceal Your Intentions','আপনার উদ্দেশ্য গোপন রাখুন','People prepare defenses against overt plans; keeping your true aims ambiguous preserves maneuverability and surprise.','মানুষ প্রকাশ্য পরিকল্পনার বিরুদ্ধে প্রতিরক্ষা প্রস্তুত করে; আপনার প্রকৃত উদ্দেশ্য অস্পষ্ট রাখলে তা চাল এবং বিস্ময় ধরে রাখে।','strategy','[{"headingEn":"Introduction","headingBn":"ভূমিকা","bodyEn":["When people know what you want, they can prepare defenses, set prices, or rearrange the field to their advantage. Keeping your aims ambiguous is not about dishonesty for its own sake; it is about preserving the freedom to maneuver until the moment is right.","The most effective moves are often the ones no one saw coming, because no one had reason to guard against them."],"bodyBn":["যখন মানুষ জানে আপনি কী চান, তারা প্রতিরক্ষা প্রস্তুত করতে, দাম নির্ধারণ করতে, বা মাঠ তাদের সুবিধায় সাজাতে পারে। আপনার উদ্দেশ্য অস্পষ্ট রাখা নিজের জন্য অসততা নয়; এটি সঠিক মুহূর্ত পর্যন্ত চাল চলার স্বাধীনতা সংরক্ষণের বিষয়।","সবচেয়ে কার্যকর পদক্ষেপগুলি প্রায়ই এমন হয় যা কেউ আসতে দেখেনি, কারণ কারো সেগুলির বিরুদ্ধে পাহারা দেওয়ার কারণ ছিল না।"]},{"headingEn":"Core Principle","headingBn":"মূল নীতি","bodyEn":["Transparency about intent lets opponents optimize against you. By contrast, ambiguity forces them to prepare for multiple possibilities, which is costly and often leads them to make wrong assumptions you can exploit."],"bodyBn":["উদ্দেশ্য সম্পর্কে স্বচ্ছতা প্রতিপক্ষকে আপনার বিরুদ্ধে অপ্টিমাইজ করতে দেয়। এর বিপরীতে, অস্পষ্টতা তাদের একাধিক সম্ভাবনার জন্য প্রস্তুতি নিতে বাধ্য করে, যা ব্যয়বহুল এবং প্রায়ই তাদের ভুল অনুমান করতে পরিচালিত করে যা আপনি কাজে লাগাতে পারেন।"]},{"headingEn":"Psychological Explanation","headingBn":"মনস্তাত্ত্বিক ব্যাখ্যা","bodyEn":["Humans are prediction machines. When we cannot form a clear prediction about someone''s intent, we experience uncertainty, which is cognitively uncomfortable. To resolve it, we tend to fill in the gap with our own assumptions, which are often wrong.","By not giving people a clear target, you let them construct a narrative that suits them, and you can act in the gap between their story and reality."],"bodyBn":["মানুষ পূর্বাভাস যন্ত্র। আমরা যখন কারো উদ্দেশ্য সম্পর্কে স্পষ্ট পূর্বাভাস গঠন করতে পারি না, আমরা অনিশ্চয়তা অনুভব করি, যা জ্ঞানীয়ভাবে অস্বস্তিকর। এটি দূর করতে, আমরা ফাঁকটি নিজেদের অনুমান দিয়ে পূরণ করি, যা প্রায়ই ভুল।","মানুষকে স্পষ্ট লক্ষ্য না দিয়ে, আপনি তাদের এমন একটি আখ্যান তৈরি করতে দেন যা তাদের মানায়, এবং আপনি তাদের গল্প এবং বাস্তবতার মধ্যে ফাঁকে কাজ করতে পারেন।"]},{"headingEn":"Real-Life Examples","headingBn":"বাস্তব উদাহরণ","bodyEn":["In a salary negotiation, revealing your target number first anchors the discussion against you. Staying vague about expectations keeps the employer guessing and can produce a better offer.","In entrepreneurship, founders who publicly announce a product direction before launch invite competitors to copy or undercut. Quietly building until launch preserves first-mover advantage.","In social life, showing all your cards too early in a new relationship can overwhelm the other person; letting understanding develop gradually builds deeper rapport."],"bodyBn":["একটি বেতন আলোচনায়, আপনার লক্ষ্য সংখ্যা আগে প্রকাশ করলে আলোচনা আপনার বিরুদ্ধে নোঙর করে। প্রত্যাশা সম্পর্কে অস্পষ্ট থাকা নিয়োগকর্তাকে অনুমানে রাখে এবং একটি ভালো প্রস্তাব তৈরি করতে পারে।","উদ্যোক্তায়, প্রতিষ্ঠাতারা যারা লঞ্চের আগে প্রকাশ্যে একটি পণ্য দিক ঘোষণা করেন তারা প্রতিযোগীদের অনুকরণ বা কম দামে প্রতিযোগিতা করতে আমন্ত্রণ জানান। লঞ্চ পর্যন্ত নীরবে তৈরি করা প্রথম-চালক সুবিধা সংরক্ষণ করে।","সামাজিক জীবনে, একটি নতুন সম্পর্কে খুব আগে সব কার্ড দেখালে অন্য ব্যক্তি অভিভূত হতে পারে; বোঝাপড়া ধীরে ধীরে গড়ে তুললে গভীরতর সম্পর্ক তৈরি হয়।"]},{"headingEn":"Practical Application","headingBn":"ব্যবহারিক প্রয়োগ","bodyEn":["Share your conclusions sparingly. In discussions, ask more questions than you answer. When you must show direction, offer multiple possible paths so observers cannot pin down the real one.","Use red herrings and genuine enthusiasm for side topics to keep your main interest from being obvious."],"bodyBn":["আপনার উপসংহার সংরক্ষণের সাথে ভাগ করুন। আলোচনায়, আপনি যা উত্তর দেন তার চেয়ে বেশি প্রশ্ন করুন। যখন আপনাকে দিক দেখাতে হবে, একাধিক সম্ভাব্য পথ দিন যাতে পর্যবেক্ষকরা প্রকৃতটি নির্ধারণ করতে না পারে।","পার্শ্ব বিষয়ে আকর্ষণ বিভ্রান্তকর এবং প্রকৃত উৎসাহ ব্যবহার করুন যাতে আপনার মূল আগ্রহ স্পষ্ট না হয়।"]},{"headingEn":"Defensive Strategy","headingBn":"প্রতিরক্ষামূলক কৌশল","bodyEn":["When someone is being unusually vague, notice it as a signal. Ask yourself what they might gain from ambiguity, and avoid filling the gap with hopeful assumptions.","Require concrete commitments before you commit your own resources."],"bodyBn":["যখন কেউ অস্বাভাবিকভাবে অস্পষ্ট থাকে, এটি একটি সংকেত হিসেবে খেয়াল করুন। নিজেকে জিজ্ঞাসা করুন তারা অস্পষ্টতা থেকে কী লাভ করতে পারে, এবং আশাবাদী অনুমান দিয়ে ফাঁক পূরণ এড়িয়ে চলুন।","আপনার নিজের সম্পদ দায়বদ্ধ করার আগে সুনির্দিষ্ট প্রতিশ্রুতি দাবি করুন।"]},{"headingEn":"When Not to Apply","headingBn":"যখন প্রয়োগ করা উচিত নয়","bodyEn":["In trust-based relationships, partners, and teams, excessive concealment erodes the openness that collaboration requires. Hidden agendas in a marriage or a founding team will eventually surface as betrayal.","Conceal intentions from competitors and counterparties, not from your closest allies."],"bodyBn":["বিশ্বাস-ভিত্তিক সম্পর্কে, অংশীদারদের মধ্যে এবং দলে, অতিরিক্ত গোপনীয়তা সেই উন্মুক্ততা ক্ষয় করে যা সহযোগিতার প্রয়োজন। একটি বিবাহ বা প্রতিষ্ঠাতা দলে গোপন উদ্দেশ্য শেষ পর্যন্ত বিশ্বাসভঙ্গ হিসেবে প্রকাশ পাবে।","প্রতিযোগী এবং পার্শ্বপক্ষের কাছ থেকে উদ্দেশ্য গোপন করুন, আপনার নিকটতম মিত্রদের কাছ থেকে নয়।"]},{"headingEn":"Ethical Considerations","headingBn":"নৈতিক বিবেচনা","bodyEn":["There is a line between privacy and deception. You have no obligation to broadcast every plan, but actively lying about your intentions crosses into manipulation that can damage your reputation if exposed.","Aim for silence and redirection rather than false statements."],"bodyBn":["গোপনীয়তা এবং প্রতারণার মধ্যে একটি সীমা রয়েছে। আপনার প্রতিটি পরিকল্পনা সম্প্রচার করার কোনো বাধ্যবাধকতা নেই, কিন্তু আপনার উদ্দেশ্য সম্পর্কে সক্রিয়ভাবে মিথ্যা বলা ম্যানিপুলেশনে প্রবেশ করে যা প্রকাশ পেলে আপনার খ্যাতি ক্ষতিগ্রস্ত করতে পারে।","মিথ্যা বিবৃতির পরিবর্তে নীরবতা এবং পুনঃনির্দেশনার লক্ষ্য রাখুন।"]},{"headingEn":"Key Takeaways","headingBn":"মূল শিক্ষা","bodyEn":["Ambiguity is a tool, not a default — use it deliberately.","Let others reveal their assumptions; act in the gap.","Be transparent with allies, guarded with competitors.","Prefer silence and redirection over active lies."],"bodyBn":["অস্পষ্টতা একটি হাতিয়ার, ডিফল্ট নয় — এটি ইচ্ছাকৃতভাবে ব্যবহার করুন।","অন্যদের তাদের অনুমান প্রকাশ করতে দিন; ফাঁকে কাজ করুন।","মিত্রদের সাথে স্বচ্ছ থাকুন, প্রতিযোগীদের সাথে সতর্ক।","সক্রিয় মিথ্যার চেয়ে নীরবতা এবং পুনঃনির্দেশনা পছন্দ করুন।"]}]'::jsonb,null,true,3) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('always-say-less-than-necessary',4,'Always Say Less Than Necessary','সবসময় প্রয়োজনের চেয়ে কম বলুন','Speaking more than needed creates openings for others to find flaws; brevity projects control and invites curiosity.','প্রয়োজনের চেয়ে বেশি বললে অন্যরা ত্রুটি খুঁজে পাওয়ার সুযোগ পায়; সংক্ষিপ্ততা নিয়ন্ত্রণ প্রকাশ করে এবং কৌতূহল আমন্ত্রণ জানায়।','perception','[]'::jsonb,null,true,4) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('so-much-depends-on-reputation-guard-it-with-your-life',5,'So Much Depends on Reputation — Guard It with Your Life','অনেক কিছু খ্যাতির ওপর নির্ভর করে — এটি জীবন দিয়ে রক্ষা করুন','Reputation is the foundation of influence; once cracked, everything built on it becomes harder to defend.','খ্যাতি হলো প্রভাবের ভিত্তি; একবার ফাটল ধরলে এর উপর নির্মিত সবকিছু রক্ষা করা কঠিন হয়ে যায়।','reputation','[]'::jsonb,null,true,5) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('court-attention-at-all-cost',6,'Court Attention at All Cost','যেকোনো মূল্যে মনোযোগ আকর্ষণ করুন','In a crowded field, being noticed is the prerequisite to being considered; anonymity is a form of powerlessness.','ভিড়ের মধ্যে, লক্ষ্য করা হওয়া বিবেচিত হওয়ার পূর্বশর্ত; নামবিহীনতা এক প্রকার ক্ষমতাহীনতা।','perception','[]'::jsonb,null,true,6) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('get-others-to-do-the-work-for-you',7,'Get Others to Do the Work for You, but Always Take the Credit','অন্যদের দিয়ে কাজ করান, কিন্তু সবসময় কৃতিত্ব নিজে নিন','Leverage the effort and expertise of others to multiply your output, while ensuring the result is attributed to your direction.','অন্যদের পরিশ্রম এবং দক্ষতা কাজে লাগিয়ে আপনার ফল বহুগুণ করুন, এবং নিশ্চিত করুন ফল আপনার নির্দেশনার কৃতিত্ব হয়।','influence','[]'::jsonb,null,true,7) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('make-other-people-come-to-you',8,'Make Other People Come to You — Use Bait if Necessary','অন্যদের আপনার কাছে আসতে দিন — প্রয়োজনে লোভ দেখান','When you approach others, you cede control of timing and terms; when they come to you, the field is yours.','আপনি অন্যদের কাছে গেলে সময় এবং শর্তের নিয়ন্ত্রণ ছেড়ে দেন; তারা আপনার কাছে এলে মাঠ আপনার।','strategy','[]'::jsonb,null,true,8) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('win-through-your-actions-never-through-argument',9,'Win Through Your Actions, Never Through Argument','তর্কের মাধ্যমে নয়, কাজের মাধ্যমে জয়লাভ করুন','Arguments rarely change minds and often breed resentment; demonstrated results persuade without creating opposition.','তর্ক কদাচিৎ মন পরিবর্তন করে এবং প্রায়ই অসন্তোষ জন্ম দেয়; প্রদর্শিত ফল বিরোধ সৃষ্টি ছাড়াই রাজি করায়।','influence','[]'::jsonb,null,true,9) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('infection-avoid-the-unhappy-and-unlucky',10,'Infection: Avoid the Unhappy and Unlucky','সংক্রমণ: অসুখী এবং দুর্ভাগা থেকে দূরে থাকুন','Emotional states are contagious; prolonged proximity to chronic negativity will pull down your own outlook and energy.','আবেগের অবস্থা সংক্রামক; দীর্ঘস্থায়ী নেতিবাচকতার নিকটতা আপনার নিজের দৃষ্টিভঙ্গি এবং শক্তি নামিয়ে দেবে।','self-mastery','[]'::jsonb,null,true,10) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('learn-to-keep-people-dependent-on-you',11,'Learn to Keep People Dependent on You','মানুষকে আপনার ওপর নির্ভরশীল রাখতে শিখুন','Independence grants leverage; if you can be replaced, your position depends on goodwill rather than necessity.','নির্ভরতাহীনতা লিভারেজ দেয়; আপনাকে প্রতিস্থাপন করা গেলে আপনার অবস্থান প্রয়োজনের চেয়ে সদিচ্ছার উপর নির্ভর করে।','power-dynamics','[]'::jsonb,null,true,11) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('use-selective-honesty-and-generosity',12,'Use Selective Honesty and Generosity to Disarm Your Victim','পরিমিত সততা ও উদারতা ব্যবহার করে প্রতিপক্ষকে নিরস্ত্র করুন','A single sincere gesture can lower defenses built over years, making later influence far easier to exert.','একটি আন্তরিক অঙ্গভঙ্গি বছরের পর বছর গড়ে তোলা প্রতিরক্ষা নামিয়ে দিতে পারে, পরবর্তী প্রভাব প্রয়োগ সহজ করে।','influence','[]'::jsonb,null,true,12) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('when-asking-for-help-appeal-to-self-interest',13,'When Asking for Help, Appeal to People''s Self-Interest, Not Their Mercy','সাহায্য চাওয়ার সময় করুণার পরিবর্তে স্বার্থে আবেদন করুন','Generosity born of pity is thin and temporary; alliances built on mutual benefit are durable and self-reinforcing.','করুণা থেকে জন্ম নেওয়া উদারতা পাতলা এবং ক্ষণস্থায়ী; পারস্পরিক স্বার্থে নির্মিত জোট টেকসই এবং স্ব-সশক্তিশালী।','relationships','[]'::jsonb,null,true,13) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('pose-as-a-friend-work-as-a-spy',14,'Pose as a Friend, Work as a Spy','বন্ধু সেজে গুপ্তচরের কাজ করুন','Information gathered in informal, trusting settings reveals far more than direct interrogation ever could.','নানুষ্ঠানিক, বিশ্বাসের পরিবেশে সংগৃহীত তথ্য সরাসরি জিজ্ঞাসাবাদের চেয়ে অনেক বেশি প্রকাশ করে।','perception','[]'::jsonb,null,true,14) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('crush-your-enemy-totally',15,'Crush Your Enemy Totally','আপনার শত্রুকে সম্পূর্ণভাবে পরাস্ত করুন','A wounded opponent has time and motive to recover and retaliate; half-measures in conflict create future threats.','আহত প্রতিপক্ষের পুনরুদ্ধার এবং প্রতিশোধের সময় ও উদ্দেশ্য থাকে; দ্বন্দ্বে অর্ধ-ব্যবস্থা ভবিষ্যৎ হুমকি তৈরি করে।','strategy','[]'::jsonb,null,true,15) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('use-absence-to-increase-respect-and-honor',16,'Use Absence to Increase Respect and Honor','অনুপস্থিতি ব্যবহার করে সম্মান বৃদ্ধি করুন','Constant presence diminishes value; strategic absence reminds people of your worth and creates demand for your return.','নিরন্তর উপস্থিতি মূল্য হ্রাস করে; কৌশলগত অনুপস্থিতি মানুষকে আপনার মূল্য মনে করিয়ে দেয় এবং ফিরে আসার চাহিদা তৈরি করে।','reputation','[]'::jsonb,null,true,16) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('keep-others-in-suspended-terror',17,'Keep Others in Suspended Terror: Cultivate an Air of Unpredictability','অন্যদের অনিশ্চয়তায় রাখুন: অনির্ণেয়তার আবেশ তৈরি করুন','Predictability lets others plan around you; unpredictability forces them to react, handing you the initiative.','পূর্বানুমেয়তা অন্যদের আপনার চারপাশে পরিকল্পনা করতে দেয়; অনির্ণেয়তা তাদের প্রতিক্রিয়া করতে বাধ্য করে, উদ্যোগ আপনাকে দেয়।','strategy','[]'::jsonb,null,true,17) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('do-not-build-fortress-to-protect-yourself',18,'Do Not Build Fortresses to Protect Yourself — Isolation Is Dangerous','নিজেকে রক্ষা করতে দুর্গ তৈরি করবেন না — বিচ্ছিন্নতা বিপজ্জনক','Cut off from information and allies, you lose touch with reality; better to circulate and know what is coming.','তথ্য এবং মিত্রদের থেকে বিচ্ছিন্ন হলে, আপনি বাস্তবতার সাথে সংযোগ হারান; চলাফেরা করে কী আসছে জানা ভালো।','self-mastery','[]'::jsonb,null,true,18) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('know-who-youre-dealing-with',19,'Know Who You''re Dealing With — Do Not Offend the Wrong Person','কার সাথে কাজ করছেন জানুন — ভুল ব্যক্তিকে অপমান করবেন না','People differ in pride, memory, and capacity for revenge; misjudging the kind of person in front of you is costly.','মানুষ গর্ব, স্মৃতি এবং প্রতিশোধের ক্ষমতায় ভিন্ন; সামনের ব্যক্তির ধরন ভুল বিচার করা ব্যয়বহুল।','relationships','[]'::jsonb,null,true,19) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('do-not-commit-to-anyone',20,'Do Not Commit to Anyone','কারো প্রতি প্রতিশ্রুতিবদ্ধ হবেন না','Remaining unattached keeps you a potential ally to all and a threat to none, preserving your options.','অাবদ্ধ না থাকলে আপনি সবার কাছে সম্ভাব্য মিত্র এবং কারো জন্য হুমকি নন, আপনার বিকল্প সংরক্ষিত রাখে।','strategy','[]'::jsonb,null,true,20) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('play-a-sucker-to-catch-a-sucker',21,'Play a Sucker to Catch a Sucker — Seem Dumber Than Your Mark','বোকার মতো আচরণ করে বোকা ধরুন — আপনার লক্ষ্যের চেয়ে বেশি বোকা মনে হন','Appearing less sharp than you are lowers others'' guard and encourages them to reveal more than they should.','আপনি যতটা তীক্ষ্ণ তার চেয়ে কম মনে হলে অন্যদের প্রতিরক্ষা কমে এবং তারা প্রয়োজনের চেয়ে বেশি প্রকাশ করতে উৎসাহিত হয়।','perception','[]'::jsonb,null,true,21) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('use-surrender-tactic-transform-weakness-into-power',22,'Use the Surrender Tactic: Transform Weakness into Power','আত্মসমর্পণ কৌশল ব্যবহার করুন: দুর্বলতাকে ক্ষমতায় রূপান্তর করুন','Surrendering before total defeat preserves resources and plants you inside the victor''s camp for a future reversal.','সম্পূর্ণ পরাজয়ের আগে আত্মসমর্পণ সম্পদ সংরক্ষণ করে এবং ভবিষ্যৎ প্রত্যাবর্তনের জন্য আপনাকে বিজয়ীর শিবিরে রাখে।','adaptability','[]'::jsonb,null,true,22) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('concentrate-your-forces',23,'Concentrate Your Forces','আপনার শক্তি কেন্দ্রীভূত করুন','Diffused effort produces mediocre results everywhere; concentrated intensity breaks through at one decisive point.','বিক্ষিপ্ত প্রচেষ্টা সর্বত্র মধ্যম ফল দেয়; কেন্দ্রীভূত তীব্রতা একটি সিদ্ধান্তমূলক বিন্দুতে সফল হয়।','strategy','[]'::jsonb,null,true,23) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('play-the-perfect-courtier',24,'Play the Perfect Courtier','নিখুঁত দরবারির ভূমিকা পালন করুন','Mastery of indirect influence — flattery, timing, and tact — often achieves what direct requests cannot.','পরোক্ষ প্রভাবের আয়ত্ত — চাটুকারিতা, সময়োপযুক্ততা এবং কৌশল — প্রায়ই সরাসরি অনুরোধের চেয়ে বেশি অর্জন করে।','influence','[]'::jsonb,null,true,24) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('re-create-yourself',25,'Re-Create Yourself','নিজেকে পুনর্নির্মাণ করুন','Identity is not fixed; crafting your persona deliberately is more powerful than accepting the role others assign.','পরিচয় স্থির নয়; আপনার ব্যক্তিত্ব ইচ্ছাকৃতভাবে তৈরি করা অন্যদের দেওয়া ভূমিকা গ্রহণের চেয়ে বেশি শক্তিশালী।','self-mastery','[]'::jsonb,null,true,25) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('keep-your-hands-clean',26,'Keep Your Hands Clean','আপনার হাত পরিষ্কার রাখুন','Use others to handle distasteful or risky tasks so your reputation remains untarnished by association.','অরুচিকর বা ঝুঁকিপূর্ণ কাজ অন্যদের দ্বারা করান যাতে আপনার খ্যাতি সংযোগে কলঙ্কিত না হয়।','reputation','[]'::jsonb,null,true,26) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('play-on-peoples-need-to-believe',27,'Play on People''s Need to Believe to Create a Cultlike Following','মানুষের বিশ্বাসের প্রয়োজন কাজে লাগিয়ে অনুগত অনুসারী তৈরি করুন','People crave meaning and certainty; offering a compelling vision attracts deeper commitment than reason alone.','মানুষ অর্থ এবং নিশ্চয়তা কামনা করে; একটি আকর্ষণীয় দৃষ্টিভঙ্গি যুক্তির চেয়ে গভীর প্রতিশ্রুতি আকর্ষণ করে।','influence','[]'::jsonb,null,true,27) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('enter-action-with-boldness',28,'Enter Action with Boldness','সাহসিকতার সাথে কাজে প্রবেশ করুন','Timidity invites doubt and obstruction; bold execution creates momentum that makes reversal hard for opponents.','ভীরুতা সন্দেহ এবং বাধা আমন্ত্রণ জানায়; সাহসী সম্পাদন ভরবেগ তৈরি করে যা প্রতিপক্ষের প্রত্যাবর্তন কঠিন করে।','strategy','[]'::jsonb,null,true,28) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('plan-all-the-way-to-the-end',29,'Plan All the Way to the End','শেষ পর্যন্ত পরিকল্পনা করুন','Thinking through consequences before acting prevents surprises and lets you shape the outcome rather than react.','কাজ করার আগে পরিণতি ভেবে দেখা বিস্ময় রোধ করে এবং প্রতিক্রিয়ার পরিবর্তে ফল গঠন করতে দেয়।','strategy','[]'::jsonb,null,true,29) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('make-your-accomplishments-seem-effortless',30,'Make Your Accomplishments Seem Effortless','আপনার অর্জনগুলো সহজসাধ্য মনে করান','Visible struggle cheapens the result; concealing the effort makes your capability appear natural and boundless.','দৃশ্যমান সংগ্রাম ফলকে সস্তা করে; পরিশ্রম গোপন করলে আপনার সক্ষমতা স্বাভাবিক এবং অসীম মনে হয়।','perception','[]'::jsonb,null,true,30) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('control-the-options-get-others-to-play-with-the-cards-you-deal',31,'Control the Options: Get Others to Play with the Cards You Deal','বিকল্প নিয়ন্ত্রণ করুন: অন্যদের আপনার দেওয়া কার্ডে খেলতে বাধ্য করুন','Framing choices so every path benefits you lets others feel they decided while you shape the outcome.','বিকল্প এমনভাবে তৈরি করুন যাতে প্রতিটি পথ আপনার উপকার করে, অন্যরা সিদ্ধান্ত নিয়েছে মনে করে যখন আপনি ফল গঠন করেন।','strategy','[]'::jsonb,null,true,31) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('play-to-peoples-fantasies',32,'Play to People''s Fantasies','মানুষের কল্পনায় খেলুন','Reality is complicated and disappointing; an appealing fantasy is easier to sell than a difficult truth.','বাস্তবতা জটিল এবং হতাশাজনক; একটি আকর্ষণীয় কল্পনা একটি কঠিন সত্যের চেয়ে বিক্রি করা সহজ।','perception','[]'::jsonb,null,true,32) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('discover-each-mans-thumbscrew',33,'Discover Each Man''s Thumbscrew','প্রত্যেকের দুর্বল স্থান আবিষ্কার করুন','Everyone has a hidden weakness or craving; finding it lets you influence them far more than frontal appeals.','প্রত্যেকের একটি গোপন দুর্বলতা বা আকাঙ্ক্ষা আছে; তা খুঁজে পেলে সরাসরি আবেদনের চেয়ে বেশি প্রভাবিত করতে পারেন।','influence','[]'::jsonb,null,true,33) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('be-royal-in-your-own-fashion',34,'Be Royal in Your Own Fashion: Act Like a King to Be Treated Like One','আপনার নিজস্ব শৈলীতে রাজকীয় হোন: রাজা হিসেবে আচরণ করুন যাতে রাজা হিসেবে আচরিত হন','How you carry yourself sets the ceiling for how others treat you; self-regard shapes external regard.','আপনি নিজেকে কীভাবে বহন করেন তা অন্যরা কীভাবে আপনাকে আচরণ করবে তার সীমা নির্ধারণ করে; আত্ম-সম্মান বাহ্যিক সম্মান গঠন করে।','self-mastery','[]'::jsonb,null,true,34) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('master-the-art-of-timing',35,'Master the Art of Timing','সময়োপযুক্ততার শিল্প আয়ত্ত করুন','Even the right move fails at the wrong moment; reading the tempo of events lets you act when impact is greatest.','এমন কি সঠিক পদক্ষেপও ভুল সময়ে ব্যর্থ হয়; ঘটনার গতি পড়লে আপনি প্রভাব সর্বোচ্চ হলে কাজ করতে পারেন।','adaptability','[]'::jsonb,null,true,35) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('disdain-things-you-cannot-have',36,'Disdain Things You Cannot Have — Ignoring Them Is the Best Revenge','যা পেতে পারবেন না তা অবজ্ঞা করুন — উপেক্ষা সেরা প্রতিশোধ','Attention confirms value; by withholding it from what denies you, you diminish its importance and protect your dignity.','মনোযোগ মূল্য নিশ্চিত করে; আপনাকে অস্বীকার করে এমন থেকে তা তুলে নিলে আপনি এর গুরুত্ব হ্রাস করেন এবং আপনার মর্যাদা রক্ষা করেন।','self-mastery','[]'::jsonb,null,true,36) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('create-compelling-spectacles',37,'Create Compelling Spectacles','আকর্ষণীয় দৃশ্যপট তৈরি করুন','Words are argued with; striking visual gestures bypass reasoning and lodge directly in memory and emotion.','শব্দের সাথে তর্ক হয়; আকর্ষণীয় দৃশ্য সংকেত যুক্তি এড়িয়ে সরাসরি স্মৃতি এবং আবেগে স্থান পায়।','perception','[]'::jsonb,null,true,37) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('think-as-you-like-but-behave-like-others',38,'Think as You Like but Behave Like Others','যেমন ইচ্ছা চিন্তা করুন কিন্তু অন্যদের মতো আচরণ করুন','Openly flaunting unconventional views invites persecution; blending in externally protects your freedom to think.','প্রকাশ্যে অপ্রচলিত মত প্রদর্শন নিপীড়ন আমন্ত্রণ জানায়; বাইরে মিশে যাওয়া চিন্তা করার স্বাধীনতা রক্ষা করে।','adaptability','[]'::jsonb,null,true,38) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('stir-up-waters-to-catch-fish',39,'Stir Up Waters to Catch Fish','পানি নেড়ে মাছ ধরুন','Anger makes opponents reckless and predictable; staying calm while they lose composure gives you the advantage.','ক্রোধ প্রতিপক্ষকে বেপরোয়া এবং পূর্বানুমেয় করে; তারা আত্মসংযম হারালে শান্ত থাকা আপনাকে সুবিধা দেয়।','strategy','[]'::jsonb,null,true,39) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('despise-the-free-lunch',40,'Despise the Free Lunch','বিনামূল্যের জিনিস ঘৃণা করুন','What is free is usually concealed in obligation or manipulation; paying fair price keeps you clear of hidden strings.','বিনামূল্যে যা পাওয়া যায় তা সাধারণত বাধ্যবাধকতা বা কারসাজিতে লুকানো; ন্যায্য মূল্য দিলে গোপন সূত্র থেকে মুক্ত থাকেন।','self-mastery','[]'::jsonb,null,true,40) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('avoid-stepping-into-a-great-mans-shoes',41,'Avoid Stepping into a Great Man''s Shoes','একজন মহান ব্যক্তির স্থান গ্রহণ এড়িয়ে চলুন','Following a celebrated predecessor guarantees unfavorable comparison; establish your own path rather than inheriting shadow.','একজন সুপরিচিত পূর্বসূরির পরে আসা অনুরূপ তুলনা নিশ্চিত করে; ছায়া উত্তরাধিকার নেওয়ার পরিবর্তে নিজস্ব পথ প্রতিষ্ঠা করুন।','self-mastery','[]'::jsonb,null,true,41) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('strike-the-shepherd-and-the-sheep-will-scatter',42,'Strike the Shepherd and the Sheep Will Scatter','রাখালকে আঘাত করুন এবং ভেড়া ছড়িয়ে পড়বে','A group''s energy often flows from one leader; separating that figure dissolves the opposition''s coherence.','একটি দলের শক্তি প্রায়ই একজন নেতার থেকে প্রবাহিত; সেই ব্যক্তিকে আলাদা করলে বিরোধিতার সংহতি দ্রবীভূত হয়।','strategy','[]'::jsonb,null,true,42) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('work-on-the-hearts-and-minds-of-others',43,'Work on the Hearts and Minds of Others','অন্যদের হৃদয় ও মনে প্রভাব ফেলুন','Coercion breeds resentment and sabotage; persuasion that reaches emotions builds durable, willing alignment.','বলপ্রয়োগ অসন্তোষ এবং ধ্বংসসাধন জন্ম দেয়; আবেগে পৌঁছানো যুক্তিবাজনা টেকসই, স্বেচ্ছাসেবী সারিবদ্ধতা গড়ে।','influence','[]'::jsonb,null,true,43) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('disarm-and-infuriate-with-the-mirror-effect',44,'Disarm and Infuriate with the Mirror Effect','প্রতিবিম্ব প্রভাব দিয়ে নিরস্ত্র এবং ক্ষুব্ধ করুন','Reflecting people''s behavior back at them reveals their hidden motives and quietly exposes their hypocrisy.','মানুষের আচরণ তাদের দিকে প্রতিফলিত করলে তাদের গোপন উদ্দেশ্য প্রকাশ পায় এবং তাদের ভণ্ডামি প্রকাশ করে।','perception','[]'::jsonb,null,true,44) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('preach-the-need-for-change',45,'Preach the Need for Change, but Never Reform Too Much at Once','পরিবর্তনের প্রয়োজন প্রচার করুন, কিন্তু কখনো একসাথে খুব বেশি সংস্কার করবেন না','People accept change in principle but resist it in practice; too much at once threatens habits and provokes backlash.','মানুষ পরিবর্তন নীতিতে গ্রহণ করে কিন্তু অনুশীলনে প্রতিরোধ করে; একসাথে খুব বেশি অভ্যাস হুমকি দেয় এবং প্রতিক্রিয়া উসকে দেয়।','adaptability','[]'::jsonb,null,true,45) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('never-appear-too-perfect',46,'Never Appear Too Perfect','কখনো খুব নিখুঁত মনে হবেন না','Perfection breeds envy and resentment; revealing a harmless flaw makes you relatable and lowers others'' defenses.','নিখুঁততা ঈর্ষা এবং অসন্তোষ জন্ম দেয়; একটি ক্ষতিহীন ত্রুটি প্রকাশ করলে আপনি সহানুভূতিশীল মনে হন এবং অন্যদের প্রতিরক্ষা কমে।','reputation','[]'::jsonb,null,true,46) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('do-not-go-past-the-mark-you-aimed-for',47,'Do Not Go Past the Mark You Aimed For — In Victory, Learn When to Stop','লক্ষ্যের চেয়ে বেশি যাবেন না — বিজয়ে থামার সময় জানুন','Success tempts overreach; pushing beyond your objective creates new enemies and squanders what you already won.','সাফল্য অতিরিক্ত প্রসারণে প্রলুব্ধ করে; লক্ষ্যের বাইরে চাপ দিলে নতুন শত্রু তৈরি হয় এবং যা জিতেছেন তা নষ্ট হয়।','self-mastery','[]'::jsonb,null,true,47) on conflict(slug) do nothing;
insert into public.content_laws(slug,number,title_en,title_bn,short_en,short_bn,category_id,sections,assessment,is_published,sort_order) values ('assume-formlessness',48,'Assume Formlessness','নিরাকার হোন','Fixed shapes can be grasped and broken; adapting fluidly to circumstances makes you impossible to pin down.','নির্দিষ্ট আকার ধরা এবং ভাঙা যায়; পরিস্থিতি অনুযায়ী তরলভাবে অভিযোজন আপনাকে নির্দিষ্ট করা অসম্ভব করে।','adaptability','[]'::jsonb,null,true,48) on conflict(slug) do nothing;
